495	function statsHTML() {
496	  const ts = flat().filter(x => !x.t.error && !isArchived(x.t));
497	  const inFlight = ts.filter(x => (x.t.task.phase || "") !== "done").length;
498	  const need = ts.filter(x => (x.t.task.phase || "") !== "done").reduce((a, x) => a + needsCount(x.t), 0);
499	  const waiting = ts.filter(x => (x.t.task.phase || "") !== "done").reduce((a, x) => a + waitCount(x.t), 0);
500	  const stale = ts.filter(x => (x.t.task.phase || "") !== "done" && isStale(x.t.mtime)).length;
501	  const friction = feedbackOpen().length;
502	  return `<div class="stat"><b>${inFlight}</b><span>in flight</span></div>` +
503	    (need ? `<div class="stat attn"><b>${need}</b><span>need you</span></div>` : "") +
504	    (waiting ? `<div class="stat wait"><b>${waiting}</b><span>waiting on</span></div>` : "") +
505	    (stale ? `<div class="stat"><b>${stale}</b><span>stale</span></div>` : "") +
506	    (friction ? `<div class="stat"><b>${friction}</b><span>friction</span></div>` : "");
507	}
508	
509	const isDone = t => !t.error && (t.task.phase || "") === "done";
510	
511	/* compact per-card roster: one chip per child, active first, state-colored */
512	const CHILD_ORDER = { active: 0, pending: 1, done: 2 };
513	const CHILD_MARK = { active: "▶ ", pending: "○ ", done: "✓ " };
514	function childrenRosterHTML(children) {
515	  if (!children.length) return `<div class="calm childrenempty">no children started yet</div>`;
516	  const sorted = children.slice().sort((a, b) => (CHILD_ORDER[a.state] ?? 1) - (CHILD_ORDER[b.state] ?? 1));
517	  return `<div class="childroster">` + sorted.map(c => {
518	    const st = c.state || "pending";
519	    return `<span class="childchip ${st}" title="${esc(c.title || c.id)} · ${esc(st)}">` +
520	      (CHILD_MARK[st] || "") + esc(c.title || c.id) + `</span>`;
521	  }).join("") + `</div>`;
522	}
523	
524	function cardHTML({ repo, t }) {
525	  if (t.error) {
526	    return `<div class="card errcard"><div class="head"><span class="t">${esc(t.file)}</span></div>` +
527	           `<span class="badge-err">parse error</span><div class="msg">${esc(t.error)}</div></div>`;
528	  }
529	  const k = t.task, n = needsCount(t), wn = waitCount(t);
530	  const stale = isStale(t.mtime) && !isDone(t);
531	  if (k.type === "epic") {
532	    const children = k.children || [];
533	    const activeN = children.filter(c => c.state === "active").length;
534	    return `<a class="card${n ? " attn" : ""}" href="#${esc(repo)}/${esc(t.id)}">` +
535	      `<div class="head"><span class="t">${esc(k.title || t.id)}</span>` +
536	      (n ? `<span class="flag">needs you · ${n}</span>` : "") +
537	      (wn ? `<span class="chip waitchip">⧖ ${wn}</span>` : "") +
538	      `<span class="chip epicbadge">◆ epic</span>` +
539	      `<span class="chip">${esc(repo)}</span></div>` +
540	      childrenRosterHTML(children) +
541	      `<div class="foot">` +
542	      `<span>${children.length} ${children.length === 1 ? "child" : "children"}` +
543	      (activeN ? ` · ${activeN} active` : "") + `</span>` +
544	      `<span class="sp"></span>${k.worklog ? "☰ " + esc(k.worklog) : ""}` +
545	      ((isDone(t) || isArchived(t)) ? " " + moveBtn(repo, t) : "") + `</div></a>`;
546	  }
547	  const meta = [
548	    k.tier !== undefined ? `tier ${esc(k.tier)}` : "",
549	    k.complexity ? `cx ${esc(k.complexity)}` : "",
550	    k.worklog ? `☰ ${esc(k.worklog)}` : "",
551	  ].filter(Boolean).join(" · ");
552	  return `<a class="card${n ? " attn" : ""}${stale ? " stale" : ""}" href="#${esc(repo)}/${esc(t.id)}">` +
553	    `<div class="head"><span class="t">${esc(k.title || t.id)}</span>` +
554	    (n ? `<span class="flag">needs you · ${n}</span>` : "") +
555	    (wn ? `<span class="chip waitchip">⧖ ${wn}</span>` : "") +
556	    (k.type === "spike" ? `<span class="chip spikebadge">◇ spike</span>` : "") +
557	    `<span class="chip">${esc(repo)}</span></div>` +
558	    trackHTML(k.phase, k.type) + metersHTML(k) +
559	    `<div class="foot">` +
560	    (t.mtime ? `<span class="dot${stale ? " old" : ""}"></span>${ago(t.mtime)}${stale ? " — stale" : ""}` : "") +
561	    `<span class="sp"></span>${meta} ${resumeBtn(k, "⧉")}` +
562	    ((isDone(t) || isArchived(t)) ? " " + moveBtn(repo, t) : "") + `</div></a>`;
563	}
564	
565	function viewBoard() {
566	  const all = flat();
567	  if (!all.length) return frictionHTML() + `<div class="empty">No tasks yet. Drop a <code>&lt;repo&gt;/&lt;task&gt;.yaml</code> into the data directory.</div>`;
568	  const live = all.filter(x => !isDone(x.t) && !isArchived(x.t));
569	  const done = all.filter(x => isDone(x.t) && !isArchived(x.t));
570	  const archived = all.filter(x => isArchived(x.t));
571	  const attn = [];
572	  live.forEach(({ repo, t }) => allNeedsYou(t).forEach(n => attn.push({ repo, t, n })));
573	  let html = "";
574	  if (attn.length) {
575	    html += `<section class="bandfold attn">` + fold("board|needsyou", `Needs you · ${attn.length}`,
576	      attn.map(({ repo, t, n }) => {
577	        const type = esc(n.type || "item");
578	        return `<div class="need"><span class="kind ${type}">${type}</span>` +
579	          `<div class="what"><a href="#${esc(repo)}/${esc(t.id)}">${esc(t.task?.title || t.id)}</a>` +
580	          `<small>${esc(n.text || "")}${n.childTitle ? " · " + esc(n.childTitle) : ""}</small></div>` +
581	          `<span class="go">${resumeBtn(t.task, "⧉ resume")}</span></div>`;
582	      }).join("")) + `</section>`;
583	  }
584	  const waits = [];
585	  live.forEach(({ repo, t }) => allWaitingOn(t).forEach(w => waits.push({ repo, t, w })));
586	  if (!attn.length) {
587	    // three-state calm line: stays honest when external questions are open
588	    html += `<div class="calm">nothing needs you${waits.length ? ` · ${waits.length} waiting on others` : ""}</div>`;
589	  }
590	  if (waits.length) {
591	    waits.sort((a, b) => (ageDays(b.w.asked) ?? -1) - (ageDays(a.w.asked) ?? -1));
592	    html += `<section class="bandfold wait">` + fold("board|waits", `Waiting on others · ${waits.length}`,
593	      waits.map(({ repo, t, w }) => {
594	        return `<div class="need"><span class="kind wait">${esc(w.who || "?")}</span>` +
595	          `<div class="what"><a href="#${esc(repo)}/${esc(t.id)}">${esc(t.task?.title || t.id)}</a>` +
596	          `<small>${esc(w.text || "")}${w.childTitle ? " · " + esc(w.childTitle) : ""}</small></div>` +
597	          `<span class="go">${w.link ? `<a class="asklink" href="${esc(safeHref(w.link))}" target="_blank" rel="noopener">↗ asked</a> ` : ""}${ageChip(w.asked)}</span></div>`;
598	      }).join("")) + `</section>`;
599	  }
600	  html += frictionHTML();
601	  const order = live.slice().sort((a, b) =>
602	    (needsCount(b.t) ? 1 : 0) - (needsCount(a.t) ? 1 : 0) ||
603	    phaseIdx(b.t.task?.phase) - phaseIdx(a.t.task?.phase) ||
604	    (b.t.mtime || 0) - (a.t.mtime || 0));
605	  html += order.length
606	    ? `<div class="grid">` + order.map(cardHTML).join("") + `</div>`
607	    : `<div class="empty">nothing in flight</div>`;
608	  if (done.length) {
609	    const recent = done.slice().sort((a, b) => (b.t.mtime || 0) - (a.t.mtime || 0));
610	    html += `<section class="donewrap">` + fold("board|done", `Done · ${done.length}`,
611	      `<div class="grid">` + recent.map(cardHTML).join("") + `</div>`) + `</section>`;
612	  }
